def schedule(requests, m):
    requests.sort(key=lambda x: x[0])
    resources = [0] * m
    count = 0
    for i in range(len(requests)):
        if resources[0] < requests[i][0]:
            resources[0] = requests[i][1]
            count += 1
        else:
            for j in range(1, m):
                if resources[j] < requests[i][0]:
                    resources[j] = requests[i][1]
                    count += 1
                    break
    return count

