import heapq

def Dijkstra(graph, start, finish):
    dist = {}
    prev = {}
    for v in graph:
        dist[v] = float('inf')
        prev[v] = None
    dist[start] = 0
    pq = []
    heapq.heappush(pq, (dist[start], start))
    while pq:
        u = heapq.heappop(pq)[1]
        if dist[u] == float('inf'):
            break
        for v in graph[u]:
            alt = dist[u] + graph[u][v]
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heapq.heappush(pq, (dist[v], v))
    return dist, prev

def solve(graph, start, finish):
    dist, prev = Dijkstra(graph, start, finish)
    path = [finish]
    while finish != start:
        finish = prev[finish]
        path.append(finish)
    path.reverse()
    return path

